The code cuts off mid-marzipan—here’s a completed version:

```python
import random

ROOMS = ["Bell tower", "Archive", "Jury room", "Rooftop"]
PEOPLE = ["Baker", "Bailiff", "Clerk", "Judge"]
THIEF = random.randrange(len(ROOMS))

seen = set()
looks_left = 3

print("Someone has stolen the courthouse's ceremonial marzipan!")
print("Use your periscope to gather evidence. You have three sweeps.\n")


def choose(prompt, options):
    """Accept either an option's number or its name."""
    choice = input(prompt).strip().lower()

    if choice.isdigit():
        index = int(choice) - 1
        if 0 <= index < len(options):
            return index

    for index, option in enumerate(options):
        if choice == option.lower():
            return index

    return None


while looks_left > 0:
    print(f"Periscope sweeps remaining: {looks_left}")
    for number, room in enumerate(ROOMS, start=1):
        print(f"  {number}. {room}")

    room_index = choose("Sweep which room? ", ROOMS)

    if room_index is None:
        print("The periscope jams. Enter a room number or name.\n")
        continue

    seen.add(room_index)
    looks_left -= 1

    if room_index == THIEF:
        print(
            f"Evidence! You see the {PEOPLE[THIEF]} hiding marzipan "
            f"in the {ROOMS[THIEF]}.\n"
        )
    else:
        print(f"You search the {ROOMS[room_index]}, but find no evidence.\n")

print("The courthouse will now hear your accusation.")
for number, person in enumerate(PEOPLE, start=1):
    print(f"  {number}. {person}")

accused = choose("Whom do you accuse? ", PEOPLE)

if accused is None:
    print("The court cannot understand your accusation. Case dismissed.")
elif accused not in seen:
    print(
        f"The court rejects your accusation: you never observed the "
        f"{PEOPLE[accused]} through the periscope."
    )
elif accused == THIEF:
    print(
        f"Your photographic evidence convicts the {PEOPLE[THIEF]}! "
        "The ceremonial marzipan is returned. You win!"
    )
else:
    print(
        f"The {PEOPLE[accused]} is innocent. Your unsupported accusation "
        "is thrown out."
    )

print(f"The thief was the {PEOPLE[THIEF]}, hiding in the {ROOMS[THIEF]}.")
```

The key mechanic is enforced by `accused not in seen`: suspicion alone isn’t enough—the player must have personally swept the suspect’s room.
